package io.github.leetcode.tree;

import io.github.leetcode.tree.TreeNodes.TreeNode;

public class DeepestLeavesSum {

    public int deepestLeavesSum(TreeNode root) {
        int depth = getDepth(root);
        return getDepthSum(root, 1, depth);
    }

    public int getDepth(TreeNode root) {
        if (root == null) return 0;

        return 1 + Math.max(getDepth(root.left), getDepth(root.right));
    }

    public int getDepthSum(TreeNode root, int level, int depth) {
        if (root == null) return 0;

        if (level == depth) {
            return root.val;
        }

        return getDepthSum(root.left, level + 1, depth) + getDepthSum(root.right, level + 1, depth);
    }

}

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left), right(right) {}
 * };
 */
class Solution {
public:
    int deepestLeavesSum(TreeNode* root) {

        if(root -> left == NULL and root -> right == NULL)
            return root -> val;

        queue<TreeNode*> q;
        q.push(root);

        int sum = 0;

        while(!q.empty()){

            int s1 = 0;
            int n = q.size();

            while(n--){

               TreeNode* temp = q.front();
               q.pop();

               if(temp -> left){

                   q.push(temp -> left);
                   s1 += temp -> left -> val;

               }

               if(temp -> right){

                   q.push(temp -> right);
                   s1 += temp -> right -> val;

               } 

            }

            if(s1 > 0)
                sum = s1;
        }

        return sum;
    }
};

